const returnItems = [];

for (const item of $input.all()) {
  try {
    // 1. Parse the stringified JSON inside the "data" property
    const rawData = JSON.parse(item.json.data);

    // 2. Map the parsed data to the required API structure
    const formattedData = {
      schemas: rawData.schemas || [],
      totalResults: rawData.totalResults || null,

      // Note: Source has capital 'R' (Resources), target needs lowercase 'r' (resources)
      resources: (rawData.Resources || []).map(user => {
        return {
          schemas: user.schemas || [],
          id: user.id || "",
          userName: user.userName || "",
          name: {
            familyName: user.name?.familyName || "",
            givenName: user.name?.givenName || "",
            middleName: user.name?.middleName || ""
          },
          displayName: user.displayName || "",
          emails: user.emails && user.emails.length > 0 ? user.emails : [],
          active: user.active || true,
          groups: (user.groups || []).map(group => ({
            value: group.value || "",
            display: group.display || "",
            $ref: group.$ref || "",
            type: group.type || ""
          })),
          meta: {
            resourceType: user.meta?.resourceType || "",
            created: user.meta?.created || "",
            lastModified: user.meta?.lastModified || "",
            location: user.meta?.location || "",
            version: user.meta?.version || ""
          },
          "urn:ietf:params:scim:schemas:extension:enterprise:2.0:User": {
            employeeNumber: user["urn:ietf:params:scim:schemas:extension:enterprise:2.0:User"]?.employeeNumber || ""
          },
          "urn:ietf:params:scim:schemas:extension:activtrak:2.0:User": {
            tracking: user["urn:ietf:params:scim:schemas:extension:activtrak:2.0:User"]?.tracking ?? true,
            userPrincipalNames: user["urn:ietf:params:scim:schemas:extension:activtrak:2.0:User"]?.userPrincipalNames || []
          }
        };
      })
    };

    // 3. Push the clean data back to n8n's workflow
    returnItems.push({ json: formattedData });

  } catch (error) {
    // If the JSON parsing fails, return a clear error in the node
    throw new Error(`Failed to parse data: ${error.message}`);
  }
}

return returnItems;

/**
 * Leave Request Pre-Analyzer
 * --------------------------
 * Pre-analyzes leave days BEFORE the LLM evaluation.
 *
 * Outputs:
 * - daysWithFD          (numeric)
 * - daysUntilStart      (calendar days from dateFiled → dateFrom)
 * - group               "A" | "B"
 * - groupReason         human-readable reason
 * - perDayBreakdown[]   each requested day with:
 * • date, dayOfWeek, isWorkDay, isHoliday, holidayName,
 * adjacentToWeekendOrHoliday, classification ("CRITICAL"|"NON_CRITICAL"|"REST_DAY"|"HOLIDAY")
 * - summary             aggregate counts
 *
 * Usage:
 * const result = analyzeLeaveRequest({ dateFiled, dateFrom, dateTo, daysWithFD, matchingStatus, workSchedule });
 */

// ─── 2026 PH Holidays ────────────────────────────────────────────────
const PH_HOLIDAYS_2026 = [
  { date: "2026-01-01", name: "New Year's Day" },
  { date: "2026-02-17", name: "EDSA Revolution Anniversary" },
  // Feb 25 is a WORKING holiday — included but flagged
  { date: "2026-02-25", name: "People Power Anniversary (Working Holiday)", working: true },
  { date: "2026-03-16", name: "Start of Ramadan (tentative)" },
  { date: "2026-03-20", name: "Araw ng Kagitingan (moved, tentative)" },
  { date: "2026-04-02", name: "Maundy Thursday" },
  { date: "2026-04-03", name: "Good Friday" },
  { date: "2026-04-04", name: "Black Saturday" },
  { date: "2026-04-09", name: "Araw ng Kagitingan" },
  { date: "2026-05-01", name: "Labor Day" },
  { date: "2026-05-27", name: "Eid'l Fitr (tentative)" },
  { date: "2026-06-12", name: "Independence Day" },
  { date: "2026-08-14", name: "Eid'l Adha (tentative)" },
  { date: "2026-08-21", name: "Ninoy Aquino Day" },
  { date: "2026-08-31", name: "National Heroes Day" },
  { date: "2026-11-01", name: "All Saints' Day" },
  { date: "2026-11-02", name: "All Souls' Day" },
  { date: "2026-11-30", name: "Bonifacio Day" },
  { date: "2026-12-08", name: "Feast of the Immaculate Conception" },
  { date: "2026-12-24", name: "Christmas Eve" },
  { date: "2026-12-25", name: "Christmas Day" },
  { date: "2026-12-30", name: "Rizal Day" },
  { date: "2026-12-31", name: "Last Day of the Year" },
];

// Build a lookup map  →  { "2026-01-01": { name, working } }
const holidayMap = {};
PH_HOLIDAYS_2026.forEach((h) => {
  holidayMap[h.date] = { name: h.name, working: !!h.working };
});

// ─── Helpers ──────────────────────────────────────────────────────────

/** Normalize any date-ish input to a local-midnight Date */
function toLocalDate(input) {
  const d = new Date(input);
  return new Date(d.getFullYear(), d.getMonth(), d.getDate());
}

/** "YYYY-MM-DD" key for a Date */
function dateKey(d) {
  const yyyy = d.getFullYear();
  const mm = String(d.getMonth() + 1).padStart(2, "0");
  const dd = String(d.getDate()).padStart(2, "0");
  return `${yyyy}-${mm}-${dd}`;
}

/** Day-of-week label */
function dayLabel(d) {
  return d.toLocaleDateString("en-US", { weekday: "long" });
}

/** Calendar day diff (dateB − dateA) */
function dayDiff(a, b) {
  return Math.round((toLocalDate(b) - toLocalDate(a)) / 86_400_000);
}

/** Generate an inclusive date range */
function dateRange(from, to) {
  const dates = [];
  let cur = toLocalDate(from);
  const end = toLocalDate(to);
  while (cur <= end) {
    dates.push(new Date(cur));
    cur.setDate(cur.getDate() + 1);
  }
  return dates;
}

/**
 * Parse "Days with FD" field.
 * Handles formats like "59D", "59", "59 days", etc.
 * Returns numeric days or null if unparseable.
 */
function parseDaysWithFD(raw) {
  if (raw == null) return null;
  const s = String(raw).trim();
  const m = s.match(/(\d+)/);
  return m ? parseInt(m[1], 10) : null;
}

// ─── Work-Schedule Parser ─────────────────────────────────────────────
/**
 * workSchedule comes from Sprout as flat keys:
 * { mondayFrom: "09:00", mondayTo: "18:00", mondayIsRestday: false,
 * saturdayFrom: "REST DAY", saturdayIsRestday: true, ... }
 *
 * Returns a Set of weekday names (e.g. "Saturday") that are REST days.
 */
function getRestDays(workSchedule) {
  const restDays = new Set();
  if (!workSchedule) return restDays;

  const days = [
    "sunday",
    "monday",
    "tuesday",
    "wednesday",
    "thursday",
    "friday",
    "saturday",
  ];

  days.forEach((day) => {
    const isRestKey = `${day}IsRestday`;
    const fromKey = `${day}From`;

    // Explicit rest day flag
    if (workSchedule[isRestKey] === true) {
      restDays.add(day.charAt(0).toUpperCase() + day.slice(1)); // "Saturday"
      return;
    }

    // Fallback: if "From" is "REST DAY" or missing → rest day
    const fromVal = workSchedule[fromKey];
    if (!fromVal || fromVal === "REST DAY") {
      restDays.add(day.charAt(0).toUpperCase() + day.slice(1));
    }
  });

  return restDays;
}

// ─── Core: Is a given date a non-working day? ─────────────────────────
/**
 * A date is non-working if:
 * 1. It falls on the employee's rest day (per schedule), OR
 * 2. It is a non-working PH holiday (working: false / undefined)
 */
function isNonWorkingDay(date, restDays) {
  const dow = dayLabel(date);
  if (restDays.has(dow)) return { nonWorking: true, reason: "rest_day" };

  const key = dateKey(date);
  const hol = holidayMap[key];
  if (hol && !hol.working) return { nonWorking: true, reason: "holiday", holidayName: hol.name };

  return { nonWorking: false };
}

// ─── Core: Critical-Day Detection ────────────────────────────────────
/**
 * A CRITICAL work day is one directly adjacent (before or after) to a
 * weekend/rest-day OR a non-working holiday.
 *
 * Logic: check day-1 and day+1. If either is non-working → CRITICAL.
 */
function isCriticalDay(date, restDays) {
  const prev = new Date(date);
  prev.setDate(prev.getDate() - 1);
  const next = new Date(date);
  next.setDate(next.getDate() + 1);

  const prevNW = isNonWorkingDay(prev, restDays);
  const nextNW = isNonWorkingDay(next, restDays);

  const adjacentDays = [];
  if (prevNW.nonWorking) adjacentDays.push({ direction: "before", ...prevNW });
  if (nextNW.nonWorking) adjacentDays.push({ direction: "after", ...nextNW });

  return {
    isCritical: adjacentDays.length > 0,
    adjacentNonWorkingDays: adjacentDays,
  };
}

// ─── Main Analyzer ───────────────────────────────────────────────────
/**
 * @param {Object} input
 * @param {string|Date} input.dateFiled    – when the leave was filed
 * @param {string|Date} input.dateFrom     – leave start
 * @param {string|Date} input.dateTo       – leave end
 * @param {string|number} input.daysWithFD – e.g. "59D"
 * @param {string} input.matchingStatus    – Sprout matching status
 * @param {Object} input.workSchedule      – Sprout workSchedule obj
 * @param {string} input.leaveType         – e.g. "Sick Leave", "Vacation Leave"
 * @returns {Object} pre-analysis result
 */
function analyzeLeaveRequest({
  dateFiled,
  dateFrom,
  dateTo,
  daysWithFD,
  matchingStatus,
  workSchedule,
  leaveType,
  zohoSubject,
  zohoDescription, // Now taking description instead of createdTime
  zohoStatus,
}) {
  // ── 1. Parse initial Days with FD ──────────────────────────────────
  const initialFdDays = parseDaysWithFD(daysWithFD);

  // ── 2. Days until start ────────────────────────────────────────────
  const daysUntilStart = dayDiff(dateFiled, dateFrom);

  // ── 3. Combined Days with FD (tenure at leave start) ───────────────
  const combinedFdDays = (initialFdDays !== null ? initialFdDays : 0) + daysUntilStart;

  // ── 4. Group determination ─────────────────────────────────────────
  //   Group A: < 60 combined days with FD  OR  status is "Unmatched"
  //   Group B: >= 60 combined days with FD AND matched
  const isUnmatched =
    matchingStatus &&
    matchingStatus.toLowerCase().includes("unmatched");

  let group, groupReason;
  if (isUnmatched) {
    group = "A";
    groupReason = `[${leaveType || "UNKNOWN"}] Status is Unmatched → must use Leave Request Form + Zoho`;
  } else if (initialFdDays === null) {
    group = "UNKNOWN";
    groupReason = `[${leaveType || "UNKNOWN"}] Could not parse Days with FD`;
  } else if (combinedFdDays < 60) {
    group = "A";
    groupReason = `[${leaveType || "UNKNOWN"}] Combined Days with FD (${combinedFdDays} = ${initialFdDays} + ${daysUntilStart} until start) is under 60 → Leave Request Form + Zoho required`;
  } else {
    group = "B";
    groupReason = `[${leaveType || "UNKNOWN"}] Combined Days with FD (${combinedFdDays} = ${initialFdDays} + ${daysUntilStart} until start) is 60+ → standard Sprout leave + FD approval`;
  }

  // ── 5. Zoho Ticket Validation (Group A) ─────────────────────────────
  let zoho = null;
  if (group === "A") {
    const hasTicket = !!(zohoSubject || zohoDescription || zohoStatus);
    let subjectValid = false;
    let startDateMatches = false;
    let statusType = zohoStatus || null;
    const issues = [];

    if (!hasTicket) {
      issues.push("No Zoho ticket found");
    } else {
      // Check subject contains "leave request" (case-insensitive)
      if (zohoSubject && zohoSubject.toLowerCase().includes("leave request")) {
        subjectValid = true;
      } else {
        issues.push(`Zoho subject does not contain 'leave request' (got: "${zohoSubject || ""}")`);
      }

      // Check if Start Date inside description matches dateFrom
      if (zohoDescription && dateFrom) {
        // Strip HTML tags for clean regex parsing (converts `</td><td...>` to spaces)
        const plainTextDesc = String(zohoDescription).replace(/<[^>]+>/g, ' ');

        // Matches "Start Date : 24-Jun-2026"
        const startDateMatch = plainTextDesc.match(/Start Date\s*:\s*([\d]{1,2}-[A-Za-z]{3}-\d{4})/i);

        if (startDateMatch && startDateMatch[1]) {
          const zohoStartDateStr = startDateMatch[1];
          const parsedZohoStart = toLocalDate(new Date(zohoStartDateStr));
          const expectedStart = toLocalDate(dateFrom);

          // Check if parsed dates are valid and equal
          if (!isNaN(parsedZohoStart.getTime()) && parsedZohoStart.getTime() === expectedStart.getTime()) {
            startDateMatches = true;
          } else {
            issues.push(`Zoho Start Date (${zohoStartDateStr}) does not match Sprout dateFrom (${dateKey(expectedStart)})`);
          }
        } else {
          issues.push("Could not find a valid 'Start Date' in Zoho ticket description");
        }
      } else {
        issues.push("Zoho description or Sprout dateFrom is missing");
      }
    }

    zoho = {
      hasTicket,
      subjectValid,
      startDateMatches,
      statusType,
      isValid: hasTicket && subjectValid && startDateMatches,
      issues,
    };
  }

  // ── 4. Per-day breakdown ───────────────────────────────────────────
  const restDays = getRestDays(workSchedule);
  const leaveDates = dateRange(dateFrom, dateTo);

  const perDayBreakdown = leaveDates.map((d) => {
    const key = dateKey(d);
    const dow = dayLabel(d);
    const nw = isNonWorkingDay(d, restDays);
    const hol = holidayMap[key] || null;

    let classification;
    if (nw.nonWorking && nw.reason === "rest_day") {
      classification = "REST_DAY";
    } else if (nw.nonWorking && nw.reason === "holiday") {
      classification = "HOLIDAY";
    } else {
      // It's a working day — check if critical
      const crit = isCriticalDay(d, restDays);
      classification = crit.isCritical ? "CRITICAL" : "NON_CRITICAL";
    }

    // Build detail object
    const entry = {
      date: key,
      dayOfWeek: dow,
      isWorkDay: !nw.nonWorking,
      isHoliday: !!hol,
      holidayName: hol ? hol.name : null,
      isWorkingHoliday: hol ? !!hol.working : false,
      classification,
    };

    // For critical days, attach adjacency info
    if (classification === "CRITICAL") {
      const crit = isCriticalDay(d, restDays);
      entry.adjacentNonWorkingDays = crit.adjacentNonWorkingDays.map((a) => ({
        direction: a.direction,
        reason: a.reason,
        detail: a.holidayName || a.reason,
      }));
    }

    return entry;
  });

  // ── 5. Summary ─────────────────────────────────────────────────────
  const totalDays = perDayBreakdown.length;
  const workDays = perDayBreakdown.filter((d) => d.isWorkDay).length;
  const criticalDays = perDayBreakdown.filter(
    (d) => d.classification === "CRITICAL"
  ).length;
  const nonCriticalDays = perDayBreakdown.filter(
    (d) => d.classification === "NON_CRITICAL"
  ).length;
  const restDayCount = perDayBreakdown.filter(
    (d) => d.classification === "REST_DAY"
  ).length;
  const holidayCount = perDayBreakdown.filter(
    (d) => d.classification === "HOLIDAY"
  ).length;

  const hasCriticalDay = criticalDays > 0;

  // ── 7. Sick Leave Med Cert Requirement ──────────────────────────────
  const isSickLeave = leaveType &&
    leaveType.toLowerCase().includes("sick");

  let sickLeave = null;
  if (isSickLeave) {
    if (group === "A") {
      sickLeave = {
        route: "ZOHO_ALLOCATION",
        medCertRequired: "N/A",
        reason: `[${leaveType}] Group A → route through Leave Request Form + Zoho (med cert matrix does not apply)`,
      };
    } else if (group === "B") {
      let medCertRequired;
      let reason;

      if (hasCriticalDay) {
        medCertRequired = true;
        reason = `[${leaveType}] Critical working day detected (${criticalDays} critical day(s)) → medical certificate REQUIRED for 1+ days`;
      } else if (workDays >= 3) {
        medCertRequired = true;
        reason = `[${leaveType}] Non-critical days only, but ${workDays} working days (3+) → medical certificate REQUIRED`;
      } else {
        medCertRequired = false;
        reason = `[${leaveType}] Non-critical days only, ${workDays} working day(s) (1-2) → NO medical certificate needed (per HR Handbook)`;
      }

      sickLeave = {
        route: "MED_CERT_MATRIX",
        medCertRequired,
        reason,
      };
    }
  }

  // ── 8. Auto-Decision ───────────────────────────────────────────────
  // Pre-determine if the request can be auto-approved/rejected
  // or needs further human/LLM review
  const isVacationLeave = leaveType &&
    leaveType.toLowerCase().includes("vacation");
  const twoWeeksNoticeMet = daysUntilStart >= 14;

  let autoDecision, autoDecisionReason;

  if (group === "A") {
    // Group A: validate Zoho ticket first
    if (!zoho.hasTicket) {
      autoDecision = "Resubmit";
      autoDecisionReason = `[${leaveType || "UNKNOWN"}] -Failure to submit leave form in ZOHO. Kindly resubmit in Sprout, then submit a leave form in Zoho: https://forms.zohopublic.com/outsourceddoers2/form/LeaveRequestTrainingNesting/formperma/CzOtZrb4dJdW_iGXV20nxK8iM1n7UViGgei6wgiOmOU`;
    } else if (!zoho.isValid) {
      autoDecision = "Resubmit";
      autoDecisionReason = `[${leaveType || "UNKNOWN"}] Group A → Zoho ticket invalid: ${zoho.issues.join("; ")} -Failure to submit leave form in ZOHO. Kindly resubmit in Sprout, then submit a leave form in Zoho: https://forms.zohopublic.com/outsourceddoers2/form/LeaveRequestTrainingNesting/formperma/CzOtZrb4dJdW_iGXV20nxK8iM1n7UViGgei6wgiOmOU`;
    } else if (zoho.statusType && zoho.statusType.toLowerCase() === "open") {
      autoDecision = "REFER_TO_ALLOCATION";
      autoDecisionReason = `[${leaveType || "UNKNOWN"}] Group A → valid Zoho ticket is Open, awaiting Allocation decision`;
    } else if (zoho.statusType && zoho.statusType.toLowerCase() === "closed") {
      autoDecision = "NEEDS_REVIEW";
      autoDecisionReason = `[${leaveType || "UNKNOWN"}] Group A → Zoho ticket is Closed, must check description for approval/rejection`;
    } else {
      autoDecision = "REFER_TO_ALLOCATION";
      autoDecisionReason = `[${leaveType || "UNKNOWN"}] Group A → valid Zoho ticket found (status: ${zoho.statusType}), routing to Allocation`;
    }

  } else if (group === "B" && isSickLeave) {
    // Sick Leave Group B: FD approval NOT required
    if (sickLeave.medCertRequired === false) {
      // Non-critical, 1-2 days → auto-approve (no docs needed)
      autoDecision = "AUTO_APPROVED";
      autoDecisionReason = `[${leaveType}] Group B, non-critical day(s), ${workDays} working day(s) → no med cert or FD approval needed → auto-approved`;
    } else {
      // Med cert required → needs doc validation (can't auto-decide)
      autoDecision = "NEEDS_REVIEW";
      autoDecisionReason = `[${leaveType}] Group B, med cert REQUIRED → must validate attached medical certificate before approval`;
    }

  } else if (group === "B" && isVacationLeave) {
    // Vacation Leave Group B: check 2 weeks notice + day type
    if (twoWeeksNoticeMet && !hasCriticalDay) {
      // 2 weeks notice met + non-critical days → auto-approve
      autoDecision = "AUTO_APPROVED";
      autoDecisionReason = `[${leaveType}] Group B, 2-week advance notice met (${daysUntilStart} days), non-critical day(s) only → auto-approved`;
    } else if (!twoWeeksNoticeMet) {
      // Late filing → needs review for exceptions
      autoDecision = "NEEDS_REVIEW";
      autoDecisionReason = `[${leaveType}] Group B, advance notice NOT met (${daysUntilStart} days, need 14) → must check for valid exception (bereavement, emergency, etc.)`;
    } else {
      // 2 weeks met but has critical days → needs FD approval validation
      autoDecision = "NEEDS_REVIEW";
      autoDecisionReason = `[${leaveType}] Group B, 2-week notice met but includes critical day(s) → requires FD approval screenshot validation`;
    }

  } else if (group === "B") {
    // Other leave types Group B: needs FD approval doc
    autoDecision = "NEEDS_REVIEW";
    autoDecisionReason = `[${leaveType || "UNKNOWN"}] Group B → requires FD approval screenshot validation`;

  } else {
    autoDecision = "NEEDS_REVIEW";
    autoDecisionReason = `[${leaveType || "UNKNOWN"}] Group could not be determined → manual review required`;
  }

  return {
    // ── Meta ─────────────────────────────────────────────────────────
    Name:             $('Filter5').item.json.Name,
    leaveType:        leaveType || "UNKNOWN",
    initialDaysWithFD: initialFdDays,
    daysUntilStart,
    combinedDaysWithFD: combinedFdDays,
    dateFiled:        dateKey(toLocalDate(dateFiled)),
    dateFrom:         dateKey(toLocalDate(dateFrom)),
    dateTo:           dateKey(toLocalDate(dateTo)),

    // ── Routing ──────────────────────────────────────────────────────
    group,
    groupReason,

    // ── Auto Decision ────────────────────────────────────────────────
    autoDecision,
    autoDecisionReason,

    // ── Zoho Validation (only present if Group A) ────────────────────
    ...(zoho ? { zoho } : {}),

    // ── Sick Leave Analysis (only present if leave type is SL) ───────
    ...(sickLeave ? { sickLeave } : {}),

    // ── Day-level detail ─────────────────────────────────────────────
    perDayBreakdown,

    // ── Aggregates ───────────────────────────────────────────────────
    summary: {
      totalCalendarDays: totalDays,
      workingDays: workDays,
      criticalDays,
      nonCriticalDays,
      restDays: restDayCount,
      holidays: holidayCount,
      hasCriticalDay,
      overallDayType: hasCriticalDay ? "CRITICAL" : "NON_CRITICAL",
    },
  };
}

// ═══════════════════════════════════════════════════════════════════════
// ██  INPUTS — Replace these values or swap in n8n expressions  ██
// ═══════════════════════════════════════════════════════════════════════

const INPUT_DATE_FILED      = $('Filter5').item.json.DateFiled;
const INPUT_DATE_FROM       = $('Filter5').item.json.DateFrom;
const INPUT_DATE_TO         = $('Filter5').item.json.DateTo;
const INPUT_DAYS_WITH_FD    = $('Get masterlist2').item.json['Days with FD'];
const INPUT_MATCHING_STATUS = $('Get masterlist2').item.json['Matching Category'];
const INPUT_WORK_SCHEDULE   = $('GEt sprout details4').item.json.workSchedule;
const INPUT_LEAVE_TYPE      = $('HTTP Request10').item.json.leaveTypeName;
const INPUT_ZOHO_SUBJECT    = $json?.data?.[0]?.subject || null;
const INPUT_ZOHO_DESCRIPTION = $json?.data?.[0]?.description || null;
const INPUT_ZOHO_STATUS     = $json?.data?.[0]?.status || null;

// ═══════════════════════════════════════════════════════════════════════
// ██  RUN — Do not edit below this line                             ██
// ═══════════════════════════════════════════════════════════════════════

const result = analyzeLeaveRequest({
  dateFiled:       INPUT_DATE_FILED,
  dateFrom:        INPUT_DATE_FROM,
  dateTo:          INPUT_DATE_TO,
  daysWithFD:      INPUT_DAYS_WITH_FD,
  matchingStatus:  INPUT_MATCHING_STATUS,
  workSchedule:    INPUT_WORK_SCHEDULE,
  leaveType:       INPUT_LEAVE_TYPE,
  zohoSubject:     INPUT_ZOHO_SUBJECT,
  zohoDescription: INPUT_ZOHO_DESCRIPTION,
  zohoStatus:      INPUT_ZOHO_STATUS,
});

return { json: result };

// 1. Get the actual attendance logs
const actualAttendanceLogsRaw = $('HTTP Request11').item.json.data || [];

// 2. Get the filed request, its logs, and the doer name
let requestData = {};
let requestedLogs = [];
let doerName = "Unknown Doer";

try {
    requestData = $('If1').item.json || {};
    requestedLogs = requestData.logs || [];

    // Safely try to get the Doer Name from the masterlist node
    if ($('Get masterlist') && $('Get masterlist').item && $('Get masterlist').item.json) {
        doerName = $('Get masterlist').item.json['Doer Name'] || doerName;
    }
} catch (e) {
    // Failsafe in case a node is empty or skipped
}

// 12-Hour AM/PM Formatter helper
const formatDateTime = (date) => {
    if (!date || isNaN(date.getTime())) return null; 
    const pad = (n) => n.toString().padStart(2, '0');

    let hours = date.getHours();
    const ampm = hours >= 12 ? 'PM' : 'AM';
    hours = hours % 12;
    hours = hours ? hours : 12; // the hour '0' should be '12'

    return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(hours)}:${pad(date.getMinutes())}:${pad(date.getSeconds())} ${ampm}`;
};

// 3. Find the 'In' and 'Out' requested logs safely to establish the shift
const inLog = requestedLogs.find(log => log.type && log.type.toLowerCase() === 'in');
const outLog = requestedLogs.find(log => log.type && log.type.toLowerCase() === 'out');

let timeIn = null;
let timeOut = null;
let timeLogicError = false;

// Apply Shift logic and Night Shift Auto-Correct
if (inLog) timeIn = new Date(inLog.dateTime);
if (outLog) timeOut = new Date(outLog.dateTime);

if (timeIn && timeOut) {
    // Auto-correct Night Shift: If Out is before In, check if adding 24 hours fixes it
    if (timeOut < timeIn) {
        const correctedTimeOut = new Date(timeOut.getTime() + (24 * 60 * 60 * 1000));
        const shiftDurationHours = (correctedTimeOut.getTime() - timeIn.getTime()) / (1000 * 60 * 60);

        if (shiftDurationHours >= 0.1 && shiftDurationHours <= 18) {
            timeOut = correctedTimeOut; // It's a valid night shift, auto-correct the math!

            // Patch the underlying request data so the matching engine uses the correct day
            const pad = (n) => n.toString().padStart(2, '0');
            outLog.dateTime = `${correctedTimeOut.getFullYear()}-${pad(correctedTimeOut.getMonth() + 1)}-${pad(correctedTimeOut.getDate())}T${pad(correctedTimeOut.getHours())}:${pad(correctedTimeOut.getMinutes())}:${pad(correctedTimeOut.getSeconds())}`;
        } else {
            timeLogicError = true; // The times are completely broken/impossible
        }
    }
}

// --- NEW: Fill in the blanks from actual attendance if one side is missing ---
if (!timeIn && timeOut) {
    // They only requested an Out. Look for their actual In punch within the last 14 hours.
    const actualIn = actualAttendanceLogsRaw.find(actual => {
        const isEmpMatch = (requestData.employeeId == actual.id || requestData.employeeId == actual.bioEmpID);
        if (!isEmpMatch || actual.inOutMode !== 0) return false;
        const actualTime = new Date(actual.logTime);
        const diffHours = (timeOut.getTime() - actualTime.getTime()) / (1000 * 60 * 60);
        return diffHours > 0 && diffHours <= 14; 
    });
    if (actualIn) timeIn = new Date(actualIn.logTime);

} else if (!timeOut && timeIn) {
    // They only requested an In. Look for their actual Out punch within the next 14 hours.
    const actualOut = actualAttendanceLogsRaw.find(actual => {
        const isEmpMatch = (requestData.employeeId == actual.id || requestData.employeeId == actual.bioEmpID);
        if (!isEmpMatch || actual.inOutMode !== 1) return false;
        const actualTime = new Date(actual.logTime);
        const diffHours = (actualTime.getTime() - timeIn.getTime()) / (1000 * 60 * 60);
        return diffHours > 0 && diffHours <= 14;
    });
    if (actualOut) timeOut = new Date(actualOut.logTime);
}

// Create the unified inout object (Sample Schedule)
const inoutCalculation = {
    name: doerName,
    in: timeIn ? formatDateTime(timeIn) : null,
    out: timeOut ? formatDateTime(timeOut) : null,
    logs: requestedLogs
};

// Simplified view of the actual attendance logs for the output summary
const simplifiedActualLogs = actualAttendanceLogsRaw.map(log => ({
    employeeId: log.bioEmpID || log.id,
    type: log.inOutMode === 0 ? "In" : "Out",
    time: formatDateTime(new Date(log.logTime))
}));

// 4. SIMPLIFIED MATCHING ENGINE (Fact-Based Verification)
const validRequests = [];
const alreadyExistsRequests = [];
const conflictingRequests = []; // For tardiness overrides or duplicates

if (!timeLogicError) {
    for (const reqLog of requestedLogs) {
        const reqTime = new Date(reqLog.dateTime);
        const reqTypeMode = reqLog.type.toLowerCase() === 'in' ? 0 : 1;

        // Find ANY actual log of the same type (In or Out) within a 14-hour radius of the request
        const relatedActualLog = actualAttendanceLogsRaw.find(actual => {
            const isEmpMatch = (requestData.employeeId == actual.id || requestData.employeeId == actual.bioEmpID);
            if (!isEmpMatch || actual.inOutMode !== reqTypeMode) return false;

            const actualTime = new Date(actual.logTime);
            const diffHours = Math.abs(actualTime.getTime() - reqTime.getTime()) / (1000 * 60 * 60);
            return diffHours <= 14; // Fits within the same shift window
        });

        if (relatedActualLog) {
            // A punch of this type already exists for this shift!
            const actualTime = new Date(relatedActualLog.logTime);
            const diffMins = Math.abs(actualTime.getTime() - reqTime.getTime()) / (1000 * 60);

            if (diffMins <= 5) {
                // Exact Match (within 5 minutes) -> They already successfully punched this!
                alreadyExistsRequests.push(reqLog);
            } else {
                // Conflict -> They are trying to override an existing punch (e.g., hiding tardiness)
                conflictingRequests.push({
                    ...reqLog,
                    conflictReason: `An actual '${reqLog.type}' punch already exists at ${formatDateTime(actualTime)}.`
                });
            }
        } else {
            // No punch of this type exists nearby. It is a genuinely missing punch!
            validRequests.push(reqLog);
        }
    }
}

// 5. Evaluate Final Output Status
let finalStatus = "";
let finalMessage = "";
const suggestions = [];

if (timeLogicError) {
    finalStatus = "NOT_SATISFIED";
    finalMessage = "The requested Out time is mathematically earlier than the In time.";
    const suggestedOut = new Date(timeOut.getTime() + (24 * 60 * 60 * 1000));
    suggestions.push(`Time Logic Error: Your requested 'Out' time is earlier than your 'In' time. If this is a night shift crossing midnight, ensure your 'Out' date is set to the NEXT day (Suggested: ${formatDateTime(suggestedOut)}).`);

} else if (conflictingRequests.length > 0) {
    finalStatus = "NOT_SATISFIED";
    finalMessage = "The request attempts to override an existing attendance punch.";
    const conflict = conflictingRequests[0];
    suggestions.push(`Override Attempted: You filed an '${conflict.type}' correction for ${formatDateTime(new Date(conflict.dateTime))}, but ${conflict.conflictReason} Time adjustments to override late punches are not permitted.`);

} else if (validRequests.length > 0 && alreadyExistsRequests.length === 0) {
    finalStatus = "SATISFIED";
    finalMessage = "The filed request provides valid logs that do not conflict with actual attendance.";
    suggestions.push("Action Item: No further action is needed on your end. Your request perfectly resolves the missing logs and is ready for manager approval.");

} else if (validRequests.length > 0 && alreadyExistsRequests.length > 0) {
    finalStatus = "PARTIALLY_SATISFIED";
    finalMessage = "Some logs were valid, but the request included logs that already exist.";
    suggestions.push("Action Item: Your request contained a valid log, but also included a punch you already successfully made. Please ensure you only file for genuinely missing punches.");

} else if (validRequests.length === 0 && alreadyExistsRequests.length > 0) {
    finalStatus = "UNNECESSARY_REQUEST";
    finalMessage = "All requested logs already perfectly exist perfectly in the actual attendance data.";
    suggestions.push("Action Item: You may cancel or withdraw this request. The exact punch times you requested already exist perfectly in the system.");

} else {
    finalStatus = "NO_ACTION_NEEDED";
    finalMessage = "No valid requested logs found to process.";
    suggestions.push("Action Item: Please verify your attendance request form.");
}

// 6. Return the comprehensive summary object
return {
    json: {
        status: finalStatus,
        message: finalMessage,
        suggestions: suggestions,
        metrics: {
            totalCorrectionsFiled: requestedLogs.length,
            validNewPunches: validRequests.length,
            alreadyExistingPunches: alreadyExistsRequests.length,
            conflictingOverrides: conflictingRequests.length
        },
        inout: inoutCalculation,                  
        validRequestedLogs: validRequests,        
        alreadyExistsLogs: alreadyExistsRequests,
        conflictingLogs: conflictingRequests,
        submittedRequestDetails: requestData,     
        actualAttendanceLogs: simplifiedActualLogs 
    }
};

// ==========================================
// PART 0: DATA SOURCES (CENTRALIZED INPUTS)
// ==========================================
const nodeCodeJS = $('Code in JavaScript').item.json;
const nodeHttpReq12 = $('HTTP Request12').item.json;
const nodeMasterlist = $('Get masterlist').item.json;
const nodeCurrent = $json;

const sources = {
  inString: nodeCodeJS.in + '+08:00',
  outString: nodeCodeJS.out + '+08:00',
  itemName: nodeCodeJS.name,
  standardLogs: nodeCodeJS.logs || [],
  activityPart1: nodeHttpReq12.activity || [],
  activityPart2: nodeCurrent.activity || [],
  rawScheduleText: nodeMasterlist['Sprout Schedule'],
  rawSchedule2: nodeMasterlist['Sprout Schedule2']
};

// ==========================================
// PART 1: SETUP & TIME RANGES
// ==========================================
const startTime = new Date(sources.inString).getTime();
let endTime = new Date(sources.outString).getTime(); 

// --- THE NIGHT SHIFT FIX ---
if (endTime < startTime) {
  endTime += (24 * 60 * 60 * 1000); 
}

const extendedEndTime = endTime + (5 * 60 * 1000);

function toLocalString(timestamp) {
  const dt = new Date(timestamp + (8 * 60 * 60 * 1000));
  return dt.toISOString().replace('Z', '+08:00');
}

const filterRange = {
  start: toLocalString(startTime),
  strict_end: toLocalString(endTime),
  extended_end: toLocalString(extendedEndTime)
};

// ==========================================
// PART 2: ACTIVITY MERGING & FILTERING
// ==========================================
const activities = [...sources.activityPart1, ...sources.activityPart2];

let rawFirstTime = null;
let rawLastTime = null;
let first_activity_str = null;
let last_activity_str = null;
let last_activity_duration_sec = 0; 
let last_activity_title_bar = null; // Added to capture titleBar

if (activities.length > 0) {
  const sortedRawActivities = [...activities].sort((a, b) => new Date(a.time).getTime() - new Date(b.time).getTime());
  rawFirstTime = sortedRawActivities[0].time;
  rawLastTime = sortedRawActivities[sortedRawActivities.length - 1].time;

  const filteredActivities = activities.filter(activity => {
    const activityTime = new Date(activity.time).getTime();
    return activityTime >= startTime && activityTime <= extendedEndTime;
  });

  if (filteredActivities.length > 0) {
    filteredActivities.sort((a, b) => new Date(a.time).getTime() - new Date(b.time).getTime());
    first_activity_str = filteredActivities[0].time;

    const lastFilteredObject = filteredActivities[filteredActivities.length - 1];
    last_activity_str = lastFilteredObject.time;
    last_activity_duration_sec = lastFilteredObject.duration || 0; 
    last_activity_title_bar = lastFilteredObject.titleBar || null; // Extracting titleBar
  }
}

const baseActivityData = {
  name: sources.itemName,
  json_activity_count: sources.activityPart2.length,
  filter_range: filterRange,
  raw_first_activity_time: rawFirstTime,
  raw_last_activity_time: rawLastTime,
  first_filtered_activity: first_activity_str,
  last_filtered_activity: last_activity_str,
  last_filtered_activity_titleBar: last_activity_title_bar // Outputting it here
};

// ==========================================
// PART 3: SAFEGUARD - STOP IF NO ACTIVITY
// ==========================================
if (!first_activity_str || !last_activity_str) {
  return {
    json: {
      ...baseActivityData,
      isMatch: false,
      missingLog: "Both",
      closestMissedTimestamp: null,
      isLate: false,
      lateMinutes: 0,
      isUnderTime: false,
      underTimeMinutes: 0,
      matchedLogs: [],
      originalLogs: sources.standardLogs,
      matchedSource: "None",
      errorReason: "No Activity Data Available" 
    }
  };
}

// ==========================================
// PART 4: EVALUATION CONSTANTS & HELPERS
// ==========================================
const firstTime = new Date(first_activity_str).getTime();
const lastTime = new Date(last_activity_str).getTime();

const ONE_HOUR = 60 * 60 * 1000;
const THIRTY_MINUTES = 30 * 60 * 1000;
const FIFTEEN_MINUTES = 15 * 60 * 1000;
const TWO_MINUTES = 2 * 60 * 1000;

function getLogTime(log) {
  const logDateStr = log.dateTime.includes('+') || log.dateTime.includes('Z') 
      ? log.dateTime 
      : `${log.dateTime}+08:00`;
  return new Date(logDateStr).getTime();
}

// Core Matching Engine
function evaluateData(testLogs, sourceName) {
  if (!testLogs || testLogs.length === 0) {
    return { isMatch: false, matchedSource: sourceName };
  }

  const expectedIn = testLogs.some(l => l.type === "In");
  const expectedOut = testLogs.some(l => l.type === "Out");

  let bestInLog = null;
  let bestOutLog = null;
  let minInDiff = Infinity;
  let minOutDiff = Infinity;

  for (const log of testLogs) {
    const logTime = getLogTime(log);

    if (log.type === "In") {
      if (logTime >= (firstTime - THIRTY_MINUTES) && logTime <= (firstTime + TWO_MINUTES)) {
        const diff = Math.abs(firstTime - logTime);
        if (diff < minInDiff) {
          minInDiff = diff;
          bestInLog = log; 
        }
      }
    } 

    if (log.type === "Out") {
      if (logTime >= (lastTime - FIFTEEN_MINUTES) && logTime <= (lastTime + ONE_HOUR)) {
        const diff = Math.abs(lastTime - logTime);
        if (diff < minOutDiff) {
          minOutDiff = diff;
          bestOutLog = log; 
        }
      }
    }
  }

  const matchedLogs = [];
  if (bestInLog) matchedLogs.push(bestInLog);
  if (bestOutLog) matchedLogs.push(bestOutLog);

  const hasIn = !!bestInLog;
  const hasOut = !!bestOutLog;

  let matchType = "None";
  let isMatchStatus = false; 

  if (hasIn && hasOut) matchType = "Both";
  else if (hasIn) matchType = "In";
  else if (hasOut) matchType = "Out";

  if (expectedIn && expectedOut) {
      if (hasIn && hasOut) isMatchStatus = true;
      else if (hasIn || hasOut) isMatchStatus = "Partial";
  } else if (expectedIn) {
      if (hasIn) isMatchStatus = true;
  } else if (expectedOut) {
      if (hasOut) isMatchStatus = true;
  }

  let missingLog = "None";
  let expectedTimestamp = null;

  if (expectedIn && expectedOut) {
    if (matchType === "In") missingLog = "Out";
    else if (matchType === "Out") missingLog = "In";
    else if (matchType === "None") missingLog = "Both";
  } else if (expectedIn && !hasIn) {
    missingLog = "In";
  } else if (expectedOut && !hasOut) {
    missingLog = "Out";
  }

  if (missingLog === "In") expectedTimestamp = first_activity_str;
  else if (missingLog === "Out") expectedTimestamp = last_activity_str;

  let lateMinutes = 0;
  let underTimeMinutes = 0;

  if (hasIn && expectedIn) {
    const inLogTime = getLogTime(bestInLog);
    if (firstTime > inLogTime) {
      lateMinutes = Math.floor((firstTime - inLogTime) / (60 * 1000));
    }
  }

  if (hasOut && expectedOut) {
    const outLogTime = getLogTime(bestOutLog);
    if (lastTime < outLogTime) {
      underTimeMinutes = Math.floor((outLogTime - lastTime) / (60 * 1000));
      const durationMinutes = Math.floor(last_activity_duration_sec / 60);
      underTimeMinutes -= durationMinutes;
      if (underTimeMinutes < 0) underTimeMinutes = 0;
    }
  }

  const outputData = {
    isMatch: isMatchStatus,          
    missingLog: missingLog,          
    closestMissedTimestamp: expectedTimestamp,
    isLate: lateMinutes > 0,                 
    lateMinutes: lateMinutes,                
    isUnderTime: underTimeMinutes > 0,       
    underTimeMinutes: underTimeMinutes,      
    matchedLogs: matchedLogs,
    originalLogs: testLogs,
    matchedSource: sourceName        
  };

  if (testLogs.length >= 2) outputData.matchType = matchType;

  if (outputData.isMatch === false && testLogs.length > 0) {
    if (testLogs[0].type === "In") outputData.originalLog = first_activity_str;
    else if (testLogs[0].type === "Out") outputData.originalLog = last_activity_str;
  }

  return outputData;
}

// ==========================================
// PART 5: PREPARE SCHEDULE DATA
// ==========================================
const rawScheduleText = sources.rawScheduleText;
const rawSchedule2 = sources.rawSchedule2;
let scheduleLogs = [];

if (rawScheduleText && typeof rawScheduleText === 'string' && rawScheduleText.includes(' - ')) {
  const parts = rawScheduleText.split(' - ');

  function parseTime(timeStr) {
    const [time, modifier] = timeStr.trim().split(' ');
    let [hours, minutes] = time.split(':');
    hours = parseInt(hours, 10);
    minutes = parseInt(minutes, 10);

    if (hours === 12 && modifier === 'AM') hours = 0;
    if (hours < 12 && modifier === 'PM') hours += 12;

    return { hours, minutes };
  }

  const baseDate = first_activity_str.split('T')[0];
  let inParts = parseTime(parts[0]);
  let outParts = parseTime(parts[1]);

  let inTimeStr = `${baseDate}T${String(inParts.hours).padStart(2, '0')}:${String(inParts.minutes).padStart(2, '0')}:00+08:00`;
  let outTimeStr = `${baseDate}T${String(outParts.hours).padStart(2, '0')}:${String(outParts.minutes).padStart(2, '0')}:00+08:00`;

  let inMs = new Date(inTimeStr).getTime();
  let outMs = new Date(outTimeStr).getTime();

  if (outMs < inMs) {
    outMs += (24 * 60 * 60 * 1000); 
    outTimeStr = new Date(outMs).toISOString();
  }

  scheduleLogs.push({ type: "In", dateTime: inTimeStr });
  scheduleLogs.push({ type: "Out", dateTime: outTimeStr });

} else if (rawSchedule2 && rawSchedule2 !== false) {
  const schedArray = Array.isArray(rawSchedule2) ? rawSchedule2 : [rawSchedule2];
  for (const s of schedArray) {
    if (s.start) scheduleLogs.push({ type: "In", dateTime: s.start });
    if (s.strict_end) scheduleLogs.push({ type: "Out", dateTime: s.strict_end });
    else if (s.end) scheduleLogs.push({ type: "Out", dateTime: s.end });
  }
}

// ==========================================
// PART 6: EXECUTION & FINAL MERGE
// ==========================================
const standardLogs = sources.standardLogs;

let filteredScheduleLogs = [...scheduleLogs];
if (standardLogs.length > 0) {
  const requestedIn = standardLogs.some(l => l.type === "In");
  const requestedOut = standardLogs.some(l => l.type === "Out");

  if (!requestedIn) filteredScheduleLogs = filteredScheduleLogs.filter(l => l.type !== "In");
  if (!requestedOut) filteredScheduleLogs = filteredScheduleLogs.filter(l => l.type !== "Out");
}

// 1. Evaluate BOTH independently
const logResult = evaluateData(standardLogs, "Logs");
const scheduleResult = evaluateData(filteredScheduleLogs, "Schedule");

// Helper to rank match status (True is better than Partial, Partial is better than False)
function getMatchScore(res) {
  if (res.isMatch === true) return 2;
  if (res.isMatch === "Partial") return 1;
  return 0;
}

const logScore = getMatchScore(logResult);
const schedScore = getMatchScore(scheduleResult);

// Calculate total penalties
const logPenalty = (logResult.lateMinutes || 0) + (logResult.underTimeMinutes || 0);
const schedPenalty = (scheduleResult.lateMinutes || 0) + (scheduleResult.underTimeMinutes || 0);

// Default to Logs
let finalResult = logResult;

if (schedScore > logScore) {
    // If Schedule gives a better overall match (e.g. Full vs Partial), it wins
    finalResult = scheduleResult;
} else if (schedScore === logScore && schedScore > 0) {
    // If BOTH have the same match status, let them compete on lowest penalty
    // We only swap to Schedule if the penalty is STRICTLY LESS. 
    // This inherently prioritizes raw logs in a tie.
    if (schedPenalty < logPenalty) {
        finalResult = scheduleResult;
    }
}

return {
  json: {
    ...baseActivityData,
    ...finalResult,
    originalLogs: standardLogs 
  }
};

